if(q.antiBot!=="any"){let s=0;if(q.antiBot==="none"){s=agent.antiBotBadge==="None"?15:agent.antiBotBadge==="Login"||agent.antiBotBadge==="Host"?13:agent.antiBotBadge==="Stealth"?12:9;addAxis("antiBot",s,16,null);}else if(q.antiBot==="login-reuse"){s=agent.antiBotBadge==="Login"?16:agent.antiBotBadge==="Stealth"?13:agent.authModel==="user_browser"||agent.authModel==="both_user_browser_and_runtime"?10:4;addAxis("antiBot",s,16,agent.antiBotBadge==="Login"?zh?"以本机真实登录态自然绕过风控，不依赖易失效的对抗补丁":"Bypasses login walls via your real local session instead of brittle evasions":null);}else if(q.antiBot==="stealth-captcha"){s=agent.antiBotBadge==="CAPTCHA"?16:agent.antiBotBadge==="Stealth"?14:agent.antiBotBadge==="Host"?10:agent.antiBotBadge==="Login"?8:2;addAxis("antiBot",s,16,agent.antiBotBadge==="CAPTCHA"||agent.antiBotBadge==="Stealth"?zh?`官方标注支持 ${agent.antiBotBadge} 级别风控处理`:`Documents ${agent.antiBotBadge} anti-bot handling in first-party docs`:null);}}

