let trust=8;if(agent.unknowns.length>0)trust -=Math.min(5,agent.unknowns.length*2.5);if(agent.antiBotBadge==="Unknown")trust -=2;if(agent.video)trust +=1;if(agent.sources.length>=2)trust +=1;trust=Math.max(0,Math.min(10,Math.round(trust)));addAxis("verification",trust,10,null);const score=maxPossible>0?Math.min(99,Math.max(15,Math.round((raw / maxPossible)*100))):50;if(reasons.length<2){reasons.push(zh?`核心规格：${perceptionLabel("zh",agent.perception)} 感知 · ${hostingLabel("zh",agent.hosting)} · MCP ${mcpLabel("zh",agent.mcp)} · ${licenseLabel("zh",agent.license)}`:`Verified specs: ${perceptionLabel("en",agent.perception)} perception, ${hostingLabel("en",agent.hosting)}, MCP ${mcpLabel("en",agent.mcp)}, ${licenseLabel("en",agent.license)}`);}
