if(agent.antiBotBadge==="Stealth"||agent.antiBotBadge==="CAPTCHA"){caveats.push(zh?"反爬与验证码求解均引用厂商公开宣称，无跨站点通用 SLA，请务必用真实目标站压测。":"Stealth/CAPTCHA capabilities are vendor-reported claims with no universal SLA; benchmark against your actual target site.");}
if(agent.id==="browser-use"&&(q.budget==="free-oss"||q.hosting==="cloud")){caveats.push(zh?"开源内核为 MIT 免费自托管；若使用 Browser Use Cloud 则按量计费（浏览器时长 + 代理流量 + 模型 Token 加成）。":"Core library is free MIT self-host; Browser Use Cloud is usage-billed (browser hours, proxy GB, and token markup).");}
if(agent.id==="stagehand"&&(q.hosting==="cloud"||q.antiBot==="stealth-captcha")){caveats.push(zh?"Stagehand SDK 本身按 MIT 开源免费；云端托管与反爬能力需搭配 Browserbase（按月/浏览器小时另行计费）。":"Stagehand SDK is MIT OSS; managed cloud sessions and stealth features bill separately via Browserbase.");}
