function recommendAgents(rawParams={},{defaultLocale="en",baseOrigin="https://browserly.maoxunxing.com"}={}){const catalog=getCatalog();const q=normalizeRecommendParams(rawParams);const locale=q.locale||(defaultLocale==="zh"?"zh":"en");const zh=locale==="zh";const survivors=[];const excluded=[];for(const agent of catalog.agents){const excl=recCheckHardExclusion(agent,q,locale);if(excl){excluded.push({id:agent.id,name:agent.name,vendor:agent.steward,reasonCode:excl.reasonCode,reason:excl.reason});continue;}
const scored=recScoreAgent(agent,q,locale);survivors.push({agent,...scored});}
survivors.sort((a,b)=>{if(b.score!==a.score)return b.score - a.score;const unkDiff=a.agent.unknowns.length - b.agent.unknowns.length;if(unkDiff!==0)return unkDiff;return a.agent.index - b.agent.index;});const picks=survivors.slice(0,q.limit).map((item,idx)=>{const a=item.agent;return{rank:idx + 1,tier:idx===0?"primary":idx===1?"runner-up":"alternative",id:a.id,name:a.name,vendor:a.steward,logo:a.logo,score:item.score,specs:{perception:a.perception,hosting:a.hosting,mcp:a.mcp,credentials:a.authModel,antiBot:a.antiBotBadge,pricing:a.pricingBadge,license:a.license},summary:a.hostingNote||a.summary,matchedReasons:item.reasons,caveats:recBuildCaveats(a,q,locale),breakdown:item.breakdown,urls:{detail:`/agent/${a.id}`,docs:a.docsUrl,repository:a.github,homepage:a.homepage},lastChecked:a.lastChecked,sources:a.sources.map((s)=>s.url)};});const relaxedSuggestions=[];if(picks.length===0){const relaxAxes=["budget","mcp","hosting","auth","perception"];for(const axis of relaxAxes){if(q[axis]==="any")continue;const alt={...q,[axis]:"any"};const count=catalog.agents.filter((a)=>!recCheckHardExclusion(a,alt,locale)).length;if(count>0){relaxedSuggestions.push({relaxAxis:axis,unlockedCount:count,message:zh?`放宽「${axis}」限制后，可解锁 ${count} 个已核验候选方案。`:`Relaxing the "${axis}" constraint unlocks ${count} verified candidate(s).`,queryUrl:recBuildQueryUrl({...alt,locale},baseOrigin)});}}}
const queryUrl=recBuildQueryUrl({...q,locale},baseOrigin);return{asOf:catalog.checked,locale,totalCatalogCount:catalog.agents.length,matchedCount:survivors.length,excludedCount:excluded.length,query:{useCase:q.useCase,auth:q.auth,hosting:q.hosting,mcp:q.mcp,antiBot:q.antiBot,budget:q.budget,perception:q.perception,limit:q.limit},picks,excluded:excluded.slice(0,8),relaxedSuggestions,stackAdvice:recBuildStackAdvice(picks,q,catalog,locale),meta:{queryUrl,curl:`curl -s "${queryUrl}"`,skillUrl:`${baseOrigin}/SKILL.md`,skillZhUrl:`${baseOrigin}/SKILL.zh-CN.md`,catalogUrl:`${baseOrigin}/api/agents`,disclaimer:zh?"基于 Browserly 官方一手文档字段进行确定性打分，非厂商商业排名；价格与反爬能力请以来源页为准。":"Deterministic match over Browserly's first-party verified fields — not a sponsored ranking. Always confirm live pricing and anti-bot behavior on primary docs."}};}
function skillRenderSnapshotTable(agents,zh){const header=zh?"| ID | 名称 | 感知 | 托管 | MCP | 凭据模型 | 反爬 | 定价 | 许可 | 核对 |":"| ID | Name | Perception | Host | MCP | Credentials | Anti-bot | Price | License | Checked |";const sep="| :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- |";const rows=agents.map((a)=>`| \`${a.id}\` | ${a.name} | ${a.perception} | ${a.hosting} | ${a.mcp} | \`${a.authModel}\` | ${a.antiBotBadge} | ${a.pricingBadge} | ${a.license} | ${a.lastChecked} |`);return[header,sep,...rows].join("\n");}
function getSkillMarkdown(locale="en",baseOrigin="https://browserly.maoxunxing.com"){const catalog=getCatalog();const zh=locale==="zh";const table=skillRenderSnapshotTable(catalog.agents,zh);if(zh){return["---","name: momo-browserly-advisor","description: 浏览器驱动型 AI Agent 与自动化方案选型顾问。结合当前代码库环境与 Browserly 一手核验事实库，根据登录态边界、托管合规、MCP 接入、感知路径、反爬强度与许可证约束，在 17+ 方案中输出可验证的首选、备选、排除原因与避坑清单。用于选择浏览器 Agent、MCP 浏览器驱动、登录态自动化或云端反爬方案；切勿替代自家应用确定性 CI/E2E 测试（应继续使用 e2e-testing / Playwright）。","---","","# Browserly Advisor — 浏览器智能体选型顾问","",`> 数据事实源：[Browserly](${baseOrigin})（最近一手核验：\`${catalog.checked}\`，收录 \`${catalog.agents.length}\` 个活跃方案，外加 Browserbase 配套设施注记）。`,"> 设计原则：**认知诚实（Epistemic Honesty）** — 严禁编造 `unknown` 价格、许可证或反爬 SLA；若常规确定性 Playwright 足够，明确告知用户无需引入重型 LLM Browser Agent。","","## 适用边界（When to Use）","","- 用户需要为 Coding Agent（Claude Code / Antigravity / Cursor / Codex）挑选或挂载浏览器驱动 / MCP 工具。","- 用户需要在本机复用已登录会话操作后台（微信/小红书/内部 ERP/CRM），或构建无人值守的云端/自托管浏览器自动化任务。","- 用户在 `playwright-mcp`、`browser-use`、`stagehand`、`skyvern`、`ego-lite`、`huashu-chrome`、`agent-browser`、`opencode-browse`、`notte` 等方案之间犹豫不决。","- 在 `e2e-testing` 或 `interactive-review` 流程中，遇到必须复用真实登录态、跨站探索或风控拦截而无法靠纯脚本覆盖时，触发本 Skill 做驱动升级选型。","","不适用场景：","- 自家 Web 应用的常规确定性回归测试与 CI 验收（请直接使用 `@playwright/test` 或 `agent-skills` 中的 `e2e-testing`）。","- 纯后端 HTTP/GraphQL API 测试（请使用 `api-testing`）。","","## 执行工作流（Workflow）","","### 1. 先自动探测当前工作区（少问废话）","在向用户提问前，先快速检查当前仓库（若处于代码项目内）：","- 技术栈与依赖：`package.json` / `pyproject.toml`（判断是否已有 Playwright、TypeScript 或 Python 环境）。","- 现有配置：`.mcp.json` / `.cursor/` / `.claude/` / `.agents/`（是否已挂载某浏览器 MCP 或 `agent-skills` 流水线）。","- 能从代码库确定的条件直接填入参数，不要重复询问用户。","","### 2. 最多追问 3 个高杠杆硬约束","仅追问无法推断的关键决策轴（可合并为一次简短提问）：","1. **场景与登录态边界（最重要）**：操作用户本机已登录会话且密码绝不上云（`local-session`），还是无人值守的独立 Profile（`isolated-profile`）或云端密钥库（`cloud-vault`）？","2. **部署与合规边界**：是否要求数据不出内网必须自托管（`self-host`），还是接受云端托管（`cloud`）？许可证是否限制为 MIT/Apache-2.0（`free-oss`，避开 AGPL/SSPL）？","3. **接入形态与风控压力**：是否必须原生 MCP（`required`），还是偏好 CLI/SDK（`sdk-cli`）？目标站点是否有强风控/CAPTCHA（`stealth-captcha`）或仅靠本机登录态即可（`login-reuse`）？","","### 3. 调用实时决策 API（优先）或降级使用离线核验矩阵","将约束映射为标准参数，调用 Browserly 确定性推荐接口：","","```bash",`curl -s "${baseOrigin}/api/recommend?useCase=coding-agent&auth=local-session&hosting=self-host&mcp=required&antiBot=none&budget=free-oss&locale=zh"`,"```","","支持的查询参数：","- `useCase`: `any` | `coding-agent` | `logged-in-ops` | `headless-pipeline` | `visual-canvas` | `hard-antibot`","- `auth`: `any` | `local-session` | `isolated-profile` | `cloud-vault`","- `hosting`: `any` | `self-host` | `cloud`","- `mcp`: `any` | `required` | `preferred` | `sdk-cli`","- `antiBot`: `any` | `none` | `login-reuse` | `stealth-captcha`","- `budget`: `any` | `free-oss` | `oss-any` | `paid-ok`","- `perception`: `any` | `dom` | `hybrid` | `vision`（可选覆盖）","- `limit`: `1..10`（默认 `3`），`locale`: `zh` | `en`","",`若需拉取完整原始目录：\`${baseOrigin}/api/agents\` 或 \`${baseOrigin}/llms.txt\`。若当前环境断网/处于无网沙盒，直接依据文末「离线核验速查表」执行同等硬排除与取舍。`,"","### 4. 输出结构化选型诊断书","交付给用户的结论必须包含以下 5 项，且全部标注核验日期与一手来源链接：","1. **首选方案（Primary Pick）**：命中理由、核心规格、官方文档与 Browserly 档案页链接。","2. **备选 / 互补方案（Runner-up）**：说明在什么拐点下切换（例如本地调试 vs 上云扩容、DOM 提速 vs 视觉兜底）。","3. **为什么不选其他热门方案（Why-Not Exclusions）**：直接引用 API 返回的 `excluded` 硬排除理由（如纯云端、无原生 MCP、AGPL/SSPL 协议冲突）。","4. **风险与未核实项警示（Caveats & Unknowns）**：明确列出 `caveats`（包含 `unknown` 字段、partial MCP、反爬无 SLA 提醒、云端额外计费边界）。","5. **下一步落地动作（Next Step）**：结合当前代码库给出具体验证步骤（先跑 3–5 条真实页面冒烟任务验证延迟与登录稳定性）。","","## 反模式红线（Anti-patterns）","","- ❌ **杀鸡用牛刀**：用户只需给自家前端写确定性回归测试时，强推重型 LLM Browser Agent（应建议原生 `@playwright/test` / `e2e-testing`）。","- ❌ **编造事实**：将矩阵里标为 `unknown` 的价格、协议或反爬能力脑补为“免费”或“支持”。","- ❌ **无视安全红线**：用户明确要求 `local-session` 或 `self-host` 时，仍推荐纯云端或需上传凭据到云端密钥库的方案。","- ❌ **隐瞒许可证风险**：在商业项目选型中推荐 `AGPL-3.0`（Skyvern）或 `SSPL-1.0`（Notte）却不提示法务评估。","- ❌ **混淆基础设施与智能体**：把 Browserbase 等按小时计费的云浏览器基础设施直接等同于完整 Agent（它属于 Stagehand 等框架的配套宿主）。","","## 交付验收标准（Done Criteria）","","- 已结合用户环境与硬约束完成实时 API 查询（或说明因离线使用了内置核验快照）。","- 明确给出首选、备选、Why-Not 排除清单、Caveats 风险提示与具体下一步。","- 所有规格结论均附带核对日期（`lastChecked`）及官方文档 / Browserly 档案来源链接，零凭空猜测。","",`## 离线兜底：一手核验快照（as_of: ${catalog.checked}）`,"",table,"",`- 配套基础设施注记：\`Browserbase\` 属于云浏览器宿主（常搭配 Stagehand 上云），不是独立的浏览器驱动智能体行。`,`- 在线交互式选型向导与最新核验档案：${baseOrigin}/`,""].join("\n");}
return["---","name: momo-browserly-advisor","description: Advisor for selecting browser-driving AI agents and browser MCP stacks. Inspects the local workspace, applies hard credential/hosting/MCP/license constraints against Browserly's first-party verified matrix, and delivers ranked picks, why-not exclusions, and epistemic caveats. Use when choosing a browser agent, MCP browser driver, logged-in session automation, or anti-bot runtime; never replace deterministic @playwright/test CI suites (use e2e-testing instead).","---","","# Browserly Advisor — Browser-Driving Agent Selection Playbook","",`> Source of truth: [Browserly](${baseOrigin}) (last verified pass: \`${catalog.checked}\`, \`${catalog.agents.length}\` active matrix rows + Browserbase companion infra note).`,"> Core rule: **Epistemic Honesty** — never fabricate `unknown` pricing, licenses, or anti-bot SLAs, and never push a heavy LLM browser agent when deterministic Playwright is the right tool.","","## When to Use","","- Choosing a browser driver or MCP server for a coding agent (Claude Code, Antigravity, Cursor, Codex).","- Automating logged-in web apps (internal ERPs, social/admin consoles) where credentials must stay in the user's local browser session.","- Selecting between `playwright-mcp`, `browser-use`, `stagehand`, `skyvern`, `ego-lite`, `huashu-chrome`, `agent-browser`, `opencode-browse`, `notte`, `browsentic`, etc.","- Escalating from `e2e-testing` or `interactive-review` when a real journey requires an existing user login session, exploratory MCP control, or anti-bot handling beyond vanilla Playwright.","","Do not use for:","- Deterministic regression or CI E2E testing on your own app (use `@playwright/test` / `e2e-testing`).","- Pure HTTP/GraphQL backend verification (use `api-testing`).","","## Workflow","","### 1. Inspect the Workspace First","Before asking questions, inspect the current repository (if inside a project):","- Runtime & stack: `package.json` / `pyproject.toml` (Node/TS vs Python, existing Playwright/CDP dependencies).","- Existing agent setup: `.mcp.json`, `.cursor/`, `.claude/`, `.agents/` (any already-configured browser MCP or `agent-skills` harness).","- Pre-fill whatever constraints are already evident from the repo.","","### 2. Clarify Missing Hard Constraints (Max 3 Questions)","Ask only what cannot be inferred, bundled into one concise turn:","1. **Scenario & Credential Boundary (decisive)**: Must reuse the user's existing local logged-in browser (`local-session`), an isolated profile/runtime (`isolated-profile`), or a managed cloud vault (`cloud-vault`)?","2. **Hosting & License Boundary**: Strict private/local deployment (`self-host`) or managed cloud (`cloud`)? Permissive MIT/Apache-2.0 required (`free-oss`), any OSS (`oss-any`), or paid SaaS acceptable (`paid-ok`)?","3. **Integration & Anti-bot Pressure**: Native MCP required (`required`) vs SDK/CLI (`sdk-cli`)? No anti-bot (`none`), real login reuse (`login-reuse`), or Stealth/CAPTCHA handling (`stealth-captcha`)?","","### 3. Query Live Recommendation Engine (Offline Fallback Included)","Call Browserly's deterministic recommendation API with the normalized constraints:","","```bash",`curl -s "${baseOrigin}/api/recommend?useCase=coding-agent&auth=local-session&hosting=self-host&mcp=required&antiBot=none&budget=free-oss&locale=en"`,"```","","Supported query parameters:","- `useCase`: `any` | `coding-agent` | `logged-in-ops` | `headless-pipeline` | `visual-canvas` | `hard-antibot`","- `auth`: `any` | `local-session` | `isolated-profile` | `cloud-vault`","- `hosting`: `any` | `self-host` | `cloud`","- `mcp`: `any` | `required` | `preferred` | `sdk-cli`","- `antiBot`: `any` | `none` | `login-reuse` | `stealth-captcha`","- `budget`: `any` | `free-oss` | `oss-any` | `paid-ok`","- `perception`: `any` | `dom` | `hybrid` | `vision` (optional override)","- `limit`: `1..10` (default `3`), `locale`: `en` | `zh`","",`Full raw catalog endpoints: \`${baseOrigin}/api/agents\` and \`${baseOrigin}/llms.txt\`. If network access is blocked/offline, evaluate the same hard constraints against the Verified Offline Snapshot table below.`,"","### 4. Deliver an Evidence-Backed Decision Dossier","Always structure the recommendation with these 5 parts, citing `lastChecked` dates and primary URLs:","1. **Primary Pick**: matched reasons, key verified specs, official docs, and Browserly `/agent/{id}` dossier link.","2. **Runner-up / Pairing**: when to switch or pair tools (e.g., local DOM speed vs cloud scale / vision fallback).","3. **Why-Not Exclusions**: cite hard exclusions from `excluded[]` so the user knows why popular peers were ruled out.","4. **Caveats & Unknowns**: explicitly surface every caveat (`unknown` fields, `partial` MCP, `AGPL-3.0`/`SSPL-1.0` copyleft review, vendor anti-bot claims without SLA, OSS vs paid cloud billing splits).","5. **Concrete Next Step**: actionable setup/smoke-test checklist (test 3–5 real journeys on target pages for latency, tokens, and session stability).","","## Anti-patterns","","- ❌ Recommending an LLM browser agent for deterministic CI tests on the user's own app when `@playwright/test` (`e2e-testing`) is cleaner and cheaper.","- ❌ Guessing or filling in `unknown` pricing, licenses, or anti-bot guarantees.","- ❌ Recommending cloud-only or cloud-vault tools when the user requires `self-host` or `local-session`.","- ❌ Recommending `AGPL-3.0` (`skyvern`) or `SSPL-1.0` (`notte`) for commercial stacks without flagging the license.","- ❌ Conflating cloud browser infrastructure (e.g. Browserbase) with a standalone browser-driving agent.","","## Done Criteria","","- Queried `/api/recommend` with verified constraints (or explicitly stated offline fallback to the snapshot table).","- Delivered Primary Pick, Runner-up, Why-Not exclusions, Caveats/Unknowns, and a concrete verification next step.","- Cited `lastChecked` dates and primary source URLs for every recommended agent with zero fabricated claims.","",`## Offline Fallback Snapshot (as_of: ${catalog.checked})`,"",table,"","- Companion infra note: `Browserbase` is cloud browser infrastructure (commonly paired with Stagehand), not a peer agent row.",`- Interactive web finder & full dossiers: ${baseOrigin}/`,""].join("\n");}
